package main

import (
	"fmt"
	"math"
)

func main() {
	var n int
	fmt.Scan(&n)

	// A number is undoubtedly lucky if it can be represented using only two digits x and y.
	// We need to count all positive integers <= n that are undoubtedly lucky.
	//
	// Approach:
	// For each pair of digits (x, y) where 0 <= x, y <= 9, generate all numbers
	// that can be formed using only digits x and y, and count those <= n.
	// However, this would overcount numbers that can be formed by multiple pairs.
	//
	// Better approach:
	// A number is undoubtedly lucky if there exist two digits x, y such that
	// all its digits are in {x, y}.
	//
	// We can think of it this way: for a number to be undoubtedly lucky,
	// the set of distinct digits in the number must have size at most 2.
	//
	// So we need to count numbers <= n where the number of distinct digits is at most 2.
	//
	// We can use digit DP to count numbers <= n with at most 2 distinct digits.
	//
	// State: position, tight, used_digits (bitmask of which digits have been used)
	// But the number of states is manageable: position up to 10, tight 2, bitmask 2^10 = 1024.
	// Total states: 10 * 2 * 1024 = 20480, which is fine.

	// Convert n to string to get digits
	nStr := fmt.Sprintf("%d", n)
	digits := make([]int, len(nStr))
	for i := 0; i < len(nStr); i++ {
		digits[i] = int(nStr[i] - '0')
	}

	// dp[pos][tight][mask] = count of ways
	// pos: current position (0 to len(digits))
	// tight: whether we are still matching the prefix of n
	// mask: bitmask of digits used so far

	memo := make([][][]int64, len(digits)+1)
	for i := range memo {
		memo[i] = make([][]int64, 2)
		for j := range memo[i] {
			memo[i][j] = make([]int64, 1<<10)
			for k := range memo[i][j] {
				memo[i][j][k] = -1
			}
		}
	}

	var dfs func(pos int, tight bool, mask int) int64
	dfs = func(pos int, tight bool, mask int) int64 {
		if pos == len(digits) {
			// Check if the number of distinct digits is at most 2
			// Count bits in mask
			count := 0
			m := mask
			for m > 0 {
				if m&1 == 1 {
					count++
				}
				m >>= 1
			}
			if count <= 2 {
				return 1
			}
			return 0
		}

		tIdx := 0
		if tight {
			tIdx = 1
		}
		if memo[pos][tIdx][mask] != -1 {
			return memo[pos][tIdx][mask]
		}

		res := int64(0)
		maxDigit := 9
		if tight {
			maxDigit = digits[pos]
		}

		for d := 0; d <= maxDigit; d++ {
			newTight := tight && (d == maxDigit)
			newMask := mask | (1 << d)
			res += dfs(pos+1, newTight, newMask)
		}

		memo[pos][tIdx][mask] = res
		return res
	}

	// We need to count positive integers, so we should not count 0.
	// The DP above counts numbers from 0 to n (with leading zeros allowed in the representation).
	// But we want positive integers, so we subtract 1 for the number 0 if it was counted.
	// Actually, the number 0 has mask = 1<<0 = 1, which has 1 distinct digit, so it would be counted.
	// But 0 is not a positive integer, so we subtract 1.

	result := dfs(0, true, 0)
